// Generated by scripts/sync-help.mjs from pzza-code-web/components/home/Scenes.tsx. Regenerate with `npm run sync:help` rather than editing.
// A client module on purpose: these scenes are static markup, and as server
// components every element would also be serialized into the page's RSC
// payload, doubling the HTML. As a client module the payload holds one reference.
/**
 * The homepage's product scenes: the grid (hero), Tasks with a race of agents,
 * Broadcast, the agent picker, devices and notifications. Each is the PzzaCode
 * desktop UI rebuilt in HTML at its real pixel size, as a window the size it
 * gets on a 1080p display, in semi-transparent mode over an abstract
 * backdrop; the card scales it down. It responds like the app
 * (components/home/Interactive.tsx). Every terminal is a real Claude Code
 * session on one of PzzaCode's repositories, captured at its tile's size.
 */
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { Brand, Term, Tile, TopBar, Window, type StripInfo } from "./AppUI";
import { AnsiScreen, answerLength, SPINNER, SPINNER_MS, type Replay } from "./ansi";
import { useScenePlayback } from "./playback";
import { BroadcastScene } from "./BroadcastScene";
import type { CaptureId } from "./captures";
import type { BackdropScene } from "./Backdrop";
import { Shot, THIS_MAC } from "./Chrome";
import { windowPanels } from "./Dropdowns";
import { ActiveCanvas, ToolsBar, WorkspaceTabs, type ToolId } from "./Interactive";

/* Card scenes show a 1440 x 900 window, the size it gets on a 1080p display,
   framed on the part the section is about. No card edge cuts the UI: a left
   or right edge falls outside the window or in a gap between tile columns,
   a top or bottom edge outside the window, in a gap between tile rows or
   between two terminal rows. A dropdown scene shows the window's right half
   (CORNER), where the panel opens; the broadcast scene steps back to show its
   whole window, the grid with the composer docked under it (1120 x 840, 2x). */
export const ZOOM_IN = { width: 720, height: 540 };
export const BROADCAST = { width: 1120, height: 840 };
export const WIN_SIZE = { width: 1440, height: 900 };
/** The window's right half over a 2 x 2 grid (topRight): from the gap between
    the two tile columns to 16px past the window's right edge, and down to the
    line between two terminal rows of the lower tiles (window y 528; their
    rows sit on a 15px grid from y 513). */
export const CORNER = { width: WIN_SIZE.width / 2 + 16, height: 552 };
/** The half-width homepage pair (devices, notifications): CORNER, 60px
    (four terminal rows) taller, so the whole Notifications panel (380 wide,
    about 520 tall at the loop's fullest) fits under the top bar. */
const PAIR = { width: CORNER.width, height: CORNER.height + 60 };
/**
 * The window's top-right corner in a card of `width`: the tools and their open
 * dropdown, 24px under the card's top edge. A card wide enough for the whole
 * window keeps it 16px in from its right edge; a narrower one starts at the
 * middle of the window, the gap between the two columns of tiles (the
 * canvas's 10px padding and gap make it x 715 to 725), so its left edge cuts
 * no tile. The top bar is clear there too: the workspace tabs are centred on
 * the window, and the active tab's name ends at x 715, its ⌥ hint starts at
 * x 725. A CORNER-wide card keeps the usual 16px right of the window.
 */
export const topRight = (width: number) => {
  const whole = width - 16 - WIN_SIZE.width;
  return { left: whole >= 16 ? whole : -WIN_SIZE.width / 2, top: 24, ...WIN_SIZE };
};
const TOP_RIGHT = topRight(CORNER.width);
/** The whole window, 1080px wide (the narrowest the app keeps its tools inline
    at): top bar, both rows of tiles and the docked composer. */
const BOTTOM = { left: 20, top: 20, width: BROADCAST.width - 40, height: BROADCAST.height - 40 };

export type Box = { left: number; top: number; width: number; height: number };

/** A whole app window: top bar (brand, workspace tabs, tools) over the canvas. */
export function AppWindow({
  open,
  agentMenu,
  version,
  box = TOP_RIGHT,
  children,
}: {
  open?: ToolId;
  agentMenu?: boolean;
  version?: string;
  box?: Box;
  children: ReactNode;
}) {
  return (
    <Window style={box}>
      <TopBar>
        <Brand version={version} />
        <WorkspaceTabs />
        <ToolsBar initial={open} panels={windowPanels({ height: box.height, agentMenu })} />
      </TopBar>
      {children}
    </Window>
  );
}

/* -------------------------------------------------------------- sessions -- */

/** The Claude Code sessions the captures come from, and their tile footers. */
export const SESSIONS = {
  api: { path: "~/fieldnotes/api", started: "00:58" },
  web: { path: "~/fieldnotes/web", started: "00:58" },
  docs: { path: "~/fieldnotes/docs", started: "01:09" },
  release: { path: "~/fieldnotes/api", started: "00:58" },
} as const;
export type SessionId = keyof typeof SESSIONS;

/** A tile running one of the captured Claude Code sessions. */
export function SessionTile({
  id,
  capture,
  kbd,
  stat,
  footer = true,
  replay,
}: {
  id: SessionId;
  capture: CaptureId;
  kbd: string;
  stat?: "notify";
  footer?: boolean;
  replay?: Replay;
}) {
  const strip: StripInfo = { session: id, branch: "main", path: SESSIONS[id].path, started: SESSIONS[id].started };
  return (
    <Tile title={id} agent="claude" stat={stat} kbd={kbd} device={THIS_MAC} strip={footer ? strip : undefined}>
      <Term>
        <AnsiScreen id={capture} replay={replay} />
      </Term>
    </Tile>
  );
}

/* ------------------------------------------------------------------ hero -- */

/** The hero's sessions, in the order the loop visits them, with the verb each
    one's captured status line ends on ("Worked for 9s" was "Working…"). */
const HERO_TILES: { id: SessionId; capture: CaptureId; kbd: string; stat?: "notify"; verb: string }[] = [
  { id: "api", capture: "api-86", kbd: "⌘1", verb: "Working" },
  { id: "web", capture: "web-86", kbd: "⌘2", stat: "notify", verb: "Crunching" },
  { id: "release", capture: "release-86", kbd: "⌘3", verb: "Churning" },
  { id: "docs", capture: "docs-86", kbd: "⌘4", verb: "Sautéing" },
];

// Claude Code's spinner, which runs out through its glyphs and back.
// The loop's pacing: the focus moves, the agent thinks, the answer comes out
// line by line, the done line stays up to be read, then the next tile.
const FOCUS_MS = 900;
const THINK_MS = 1500;
const LINE_MS = 150;
const SETTLE_MS = 450;
const READ_MS = 2600;

interface HeroReplay {
  tile: number;
  shown: number;
  working: boolean;
  startedAt: number;
}

/**
 * The hero's grid at work: the focus walks the four sessions, and in each one
 * Claude Code writes its last answer again, the spinner and elapsed time on
 * its working line, until the done line comes back. A click or keystroke in
 * the grid stops the loop and leaves the visitor in charge, as in the app.
 */
function HeroCanvas() {
  const canvas = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(0);
  const [replay, setReplay] = useState<HeroReplay | null>(null);
  const [stopped, setStopped] = useState(false);
  const [now, setNow] = useState(0);
  const lengths = useMemo(() => HERO_TILES.map((tile) => answerLength(tile.capture)), []);

  useScenePlayback(
    canvas,
    async (wait) => {
      for (let tile = 0; tile < HERO_TILES.length; tile += 1) {
        setActive(tile);
        await wait(FOCUS_MS);
        setReplay({ tile, shown: 0, working: true, startedAt: performance.now() });
        await wait(THINK_MS);
        for (let shown = 1; shown <= lengths[tile]; shown += 1) {
          setReplay((current) => current && { ...current, shown });
          await wait(LINE_MS);
        }
        await wait(SETTLE_MS);
        setReplay((current) => current && { ...current, working: false });
        await wait(READ_MS);
        setReplay(null);
      }
    },
    { stopped, onStop: () => setReplay(null) },
  );

  // The spinner and its clock only tick while an agent is working.
  const working = replay?.working ?? false;
  useEffect(() => {
    if (!working) return;
    const timer = window.setInterval(() => setNow(performance.now()), SPINNER_MS);
    return () => window.clearInterval(timer);
  }, [working]);

  // Any click or keystroke in the grid hands it to the visitor.
  useEffect(() => {
    const element = canvas.current;
    if (!element || stopped) return;
    const takeOver = () => setStopped(true);
    element.addEventListener("pointerdown", takeOver);
    element.addEventListener("keydown", takeOver);
    return () => {
      element.removeEventListener("pointerdown", takeOver);
      element.removeEventListener("keydown", takeOver);
    };
  }, [stopped]);

  const replayFor = (index: number): Replay | undefined => {
    if (!replay || replay.tile !== index) return undefined;
    if (!replay.working) return { shown: replay.shown, working: null };
    const elapsed = Math.max(0, now - replay.startedAt);
    const glyph = SPINNER[Math.floor(elapsed / SPINNER_MS) % SPINNER.length];
    const seconds = Math.floor(elapsed / 1000) + 1;
    return {
      shown: replay.shown,
      working: { glyph, text: `${HERO_TILES[index].verb}… (${seconds}s · esc to interrupt)` },
    };
  };

  return (
    <ActiveCanvas
      canvasRef={canvas}
      active={active}
      onActivate={setActive}
      style={{ gridTemplateColumns: "1fr 1fr", gridTemplateRows: "1fr 1fr" }}
      tiles={HERO_TILES.map((tile, index) => (
        <SessionTile key={tile.id} id={tile.id} capture={tile.capture} kbd={tile.kbd} stat={tile.stat} replay={replayFor(index)} />
      ))}
    />
  );
}

export function HeroShot({ version }: { version?: string }) {
  // The hero card is 1177 x 637 on the page; the scene is that shape at 1.27x,
  // a 1412px window (its size on a 1080p display) with four sessions in a 2 x 2 grid.
  return (
    <Shot id="hero" width={1500} height={812}>
      <AppWindow version={version} box={{ left: 44, top: 62, width: 1412, height: 800 }}>
        <HeroCanvas />
      </AppWindow>
    </Shot>
  );
}

/* ----------------------------------------------------------------- tasks -- */

export const TASK_SLUG = "add-search-to-the-notes-page";

export function TasksShot() {
  // The race's three attempts beside the session they started from, in the
  // right half of a 2 x 2 grid: the first attempt under the open Tasks panel,
  // the third below it.
  return (
    <Shot id="tasks" width={CORNER.width} height={CORNER.height}>
      <AppWindow open="tasks">
        <ActiveCanvas
          initial={1}
          style={{ gridTemplateColumns: "1fr 1fr", gridTemplateRows: "1fr 1fr" }}
          tiles={[
            <SessionTile key="web" id="web" capture="web-86" kbd="⌘1" />,
            // The three attempts, each a Claude Code session on its own worktree.
            ...([1, 2, 3] as const).map((n) => {
              const name = `${TASK_SLUG}-claude-${n}`;
              return (
                <Tile
                  key={name}
                  title={name}
                  agent="claude"
                  stat="notify"
                  kbd={`⌘${n + 1}`}
                  device={THIS_MAC}
                  strip={{ session: name, branch: `pzza/${name}`, dirty: true, worktree: true, path: `~/fieldnotes/web.worktrees/${name}` }}
                >
                  <Term>
                    <AnsiScreen id={`att-${n}`} />
                  </Term>
                </Tile>
              );
            }),
          ]}
        />
      </AppWindow>
    </Shot>
  );
}

